 12 │ export interface ToolMiddlewareContext {
 13 │   toolName: string;
 14 │   args: Record<string, any>;
 15 │   workspace: string;
 16 │ }
 17 │ 
 18 │ export interface ToolPostMiddlewareContext extends ToolMiddlewareContext {
 19 │   result: ExecutionResult;
