 22 │ export interface PluginHooks {
 23 │   name: string;
 24 │   description?: string;
 25 │   onTurnStart?: (context: { prompt: string; workspace: string }) => Promise<void> | void;
 26 │   onToolCall?: (context: { toolName: string; args: Record<string, any> }) => Promise<void> | void;
 27 │   onToolResult?: (context: { toolName: string; result: ExecutionResult }) => Promise<void> | void;
 28 │   // Candidate #41: Chain-of-responsibility middleware pipeline
 29 │   preToolExecution?: (
 30 │     context: ToolMiddlewareContext,
 31 │     next: (modifiedArgs?: Record<string, any>) => Promise<ExecutionResult>
 32 │   ) => Promise<ExecutionResult>;
 33 │   postToolExecution?: (
 34 │     context: ToolPostMiddlewareContext
 35 │   ) => Promise<ExecutionResult> | ExecutionResult;
 36 │   onTurnEnd?: (context: { summary: string; isFinished: boolean }) => Promise<void> | void;
 37 │   customTools?: Array<{
 38 │     definition: ToolDefinition;
 39 │     handler: (args: Record<string, any>) => Promise<ExecutionResult>;
 40 │   }>;
 41 │ }
