 43 │ /** Directories Nexus loads plugin modules (`*.js`, `*.mjs`) from at turn start (REQ-SEC-115). */
 44 │ export function pluginDirs(workspace: string, isWorkspaceTrusted = false): string[] {
 45 │   const dirs = [
 46 │     path.join(os.homedir(), ".nexus", "plugins"),
 47 │     path.join(os.homedir(), ".config", "nexus", "plugins"),
 48 │   ];
 49 │   if (isWorkspaceTrusted) dirs.unshift(...WORKSPACE_PLUGIN_DIRS.map((dir) => path.join(workspace, dir)));
 50 │   return dirs;
 51 │ }
