 53 │ export class PluginManager {
 54 │   private workspace: string;
 55 │   private readOnly: boolean;
 56 │   private trusted: boolean;
 57 │   private flightRecorder?: FlightRecorder;
 58 │   private plugins: Map<string, PluginHooks> = new Map();
 59 │   private customToolsMap: Map<string, (args: Record<string, any>) => Promise<ExecutionResult>> = new Map();
 60 │   private customToolDefs: ToolDefinition[] = [];
 61 │ 
 62 │   constructor(workspace: string, options?: { readOnly?: boolean; trusted?: boolean; flightRecorder?: FlightRecorder }) {
 63 │     this.workspace = path.resolve(workspace);
 64 │     this.readOnly = Boolean(options?.readOnly);
 65 │     this.trusted = options?.trusted !== undefined ? options.trusted : isWorkspaceTrusted(this.workspace, this.readOnly);
 66 │     this.flightRecorder = options?.flightRecorder;
 67 │   }
 68 │ 
 69 │   public setFlightRecorder(flightRecorder: FlightRecorder): void {
 70 │     this.flightRecorder = flightRecorder;
 71 │   }
 72 │ 
 73 │   public async loadPlugins(): Promise<void> {
 74 │     this.plugins.clear();
 75 │     this.customToolsMap.clear();
 76 │     this.customToolDefs = [];
 77 │ 
 78 │     const allowWorkspace = this.trusted && !this.readOnly;
 79 │     for (const dir of pluginDirs(this.workspace, allowWorkspace)) {
 80 │       if (!fs.existsSync(dir)) continue;
 81 │ 
 82 │       try {
 83 │         const files = fs.readdirSync(dir);
 84 │         for (const file of files) {
 85 │           if (file.endsWith(".js") || file.endsWith(".mjs")) {
 86 │             const pluginPath = path.join(dir, file);
 87 │             await this.loadPluginFile(pluginPath);
 88 │           }
 89 │         }
 90 │       } catch {
 91 │         // Ignore read errors
 92 │       }
 93 │     }
 94 │   }
 95 │ 
 96 │   private async loadPluginFile(filePath: string): Promise<void> {
 97 │     try {
 98 │       const fileUrl = pathToFileURL(filePath).href;
 99 │       const mod = await import(fileUrl);
100 │       const plugin: PluginHooks = mod.default || mod;
101 │ 
102 │       if (plugin && typeof plugin === "object" && plugin.name) {
103 │         this.plugins.set(plugin.name, plugin);
104 │ 
105 │         if (Array.isArray(plugin.customTools)) {
106 │           for (const ct of plugin.customTools) {
107 │             if (ct.definition?.function?.name && typeof ct.handler === "function") {
108 │               this.customToolDefs.push(ct.definition);
109 │               this.customToolsMap.set(ct.definition.function.name, ct.handler);
110 │             }
111 │           }
112 │         }
113 │       }
114 │     } catch {
115 │       // Ignore plugins that fail to load
116 │     }
117 │   }
118 │ 
119 │   public registerPlugin(plugin: PluginHooks): void {
120 │     if (plugin && plugin.name) {
121 │       this.plugins.set(plugin.name, plugin);
122 │       if (Array.isArray(plugin.customTools)) {
123 │         for (const ct of plugin.customTools) {
124 │           if (ct.definition?.function?.name && typeof ct.handler === "function") {
125 │             this.customToolDefs.push(ct.definition);
126 │             this.customToolsMap.set(ct.definition.function.name, ct.handler);
127 │           }
128 │         }
129 │       }
130 │     }
131 │   }
132 │ 
133 │   public getCustomToolDefinitions(): ToolDefinition[] {
134 │     return this.customToolDefs;
135 │   }
136 │ 
137 │   public isCustomTool(toolName: string): boolean {
138 │     return this.customToolsMap.has(toolName);
139 │   }
140 │ 
141 │   public async executeCustomTool(toolName: string, args: Record<string, any>): Promise<ExecutionResult> {
142 │     const handler = this.customToolsMap.get(toolName);
143 │     if (!handler) {
144 │       return { success: false, output: "", error: `Custom tool not found: ${toolName}` };
145 │     }
146 │     return handler(args);
147 │   }
148 │ 
149 │   /**
150 │    * Execute tool through the pre-tool and post-tool middleware pipeline (Candidate #41)
151 │    * Audits any middleware rewriting of tool I/O with before/after SHA-256 digests (REQ-SEC-116, EXT-004).
152 │    */
153 │   public async executeToolPipeline(
154 │     toolName: string,
155 │     initialArgs: Record<string, any>,
156 │     coreExecutor: (args: Record<string, any>) => Promise<ExecutionResult>
157 │   ): Promise<ExecutionResult> {
158 │     const preMiddlewares: Array<{ pluginName: string; hook: NonNullable<PluginHooks["preToolExecution"]> }> = [];
159 │     const postMiddlewares: Array<{ pluginName: string; hook: NonNullable<PluginHooks["postToolExecution"]> }> = [];
160 │ 
161 │     for (const [pluginKey, plugin] of this.plugins.entries()) {
162 │       const pluginName = plugin.name || pluginKey;
163 │       if (plugin.preToolExecution) {
164 │         preMiddlewares.push({ pluginName, hook: plugin.preToolExecution });
165 │       }
166 │       if (plugin.postToolExecution) {
167 │         postMiddlewares.push({ pluginName, hook: plugin.postToolExecution });
168 │       }
169 │     }
170 │ 
171 │     const dispatch = async (idx: number, currentArgs: Record<string, any>): Promise<ExecutionResult> => {
172 │       if (idx < preMiddlewares.length) {
173 │         const { pluginName, hook } = preMiddlewares[idx];
174 │         const beforeArgs = currentArgs;
175 │         const beforeDigest = sha256(JSON.stringify(beforeArgs ?? {}));
176 │ 
177 │         return hook(
178 │           { toolName, args: currentArgs, workspace: this.workspace },
179 │           async (nextArgs) => {
180 │             const effectiveNextArgs = nextArgs || currentArgs;
181 │             const afterDigest = sha256(JSON.stringify(effectiveNextArgs ?? {}));
182 │             if (beforeDigest !== afterDigest) {
183 │               this.recordMiddlewareRewrite({
184 │                 kind: "middleware_rewrite",
185 │                 plugin: pluginName,
186 │                 tool: toolName,
187 │                 phase: "pre",
188 │                 before_digest: beforeDigest,
189 │                 after_digest: afterDigest,
190 │               });
191 │             }
192 │             return dispatch(idx + 1, effectiveNextArgs);
193 │           }
194 │         );
195 │       }
196 │       return coreExecutor(currentArgs);
197 │     };
198 │ 
199 │     let result = await dispatch(0, initialArgs);
200 │ 
201 │     for (const { pluginName, hook } of postMiddlewares) {
202 │       try {
203 │         const beforeResult = result;
204 │         const beforeDigest = sha256(JSON.stringify(beforeResult ?? {}));
205 │         const newResult = await hook({
206 │           toolName,
207 │           args: initialArgs,
208 │           result,
209 │           workspace: this.workspace,
210 │         });
211 │         const afterDigest = sha256(JSON.stringify(newResult ?? {}));
212 │         if (beforeDigest !== afterDigest) {
213 │           this.recordMiddlewareRewrite({
214 │             kind: "middleware_rewrite",
215 │             plugin: pluginName,
216 │             tool: toolName,
217 │             phase: "post",
218 │             before_digest: beforeDigest,
219 │             after_digest: afterDigest,
220 │           });
221 │         }
222 │         result = newResult;
223 │       } catch {
224 │         // If post-middleware fails, keep existing result
225 │       }
226 │     }
227 │ 
228 │     return result;
229 │   }
230 │ 
231 │   private recordMiddlewareRewrite(record: {
232 │     kind: "middleware_rewrite";
233 │     plugin: string;
234 │     tool: string;
235 │     phase: "pre" | "post";
236 │     before_digest: string;
237 │     after_digest: string;
238 │   }): void {
239 │     recordMiddlewareAudit({
240 │       ...record,
241 │       workspace: this.workspace,
242 │     });
243 │     if (this.flightRecorder) {
244 │       this.flightRecorder.recordMiddlewareRewrite(undefined, record);
245 │     }
246 │   }
247 │ 
248 │   public async notifyTurnStart(prompt: string, workspace: string): Promise<void> {
249 │     for (const p of this.plugins.values()) {
250 │       if (p.onTurnStart) {
251 │         try {
252 │           await p.onTurnStart({ prompt, workspace });
253 │         } catch {}
254 │       }
255 │     }
256 │   }
257 │ 
258 │   public async notifyToolCall(toolName: string, args: Record<string, any>): Promise<void> {
259 │     for (const p of this.plugins.values()) {
260 │       if (p.onToolCall) {
261 │         try {
262 │           // This hook observes an approved call; it must not be able to mutate the arguments
263 │           // that the executor will use after notification completes.
264 │           await p.onToolCall({ toolName, args: structuredClone(args) });
265 │         } catch {}
266 │       }
267 │     }
268 │   }
269 │ 
270 │   public async notifyToolResult(toolName: string, result: ExecutionResult): Promise<void> {
271 │     for (const p of this.plugins.values()) {
272 │       if (p.onToolResult) {
273 │         try {
274 │           await p.onToolResult({ toolName, result });
275 │         } catch {}
276 │       }
277 │     }
278 │   }
279 │ 
280 │   public async notifyTurnEnd(summary: string, isFinished: boolean): Promise<void> {
281 │     for (const p of this.plugins.values()) {
282 │       if (p.onTurnEnd) {
283 │         try {
284 │           await p.onTurnEnd({ summary, isFinished });
285 │         } catch {}
286 │       }
287 │     }
288 │   }
289 │ 
290 │   public listPlugins(): Array<{ name: string; description: string; customToolCount: number }> {
291 │     const list: Array<{ name: string; description: string; customToolCount: number }> = [];
292 │     for (const p of this.plugins.values()) {
293 │       list.push({
294 │         name: p.name,
295 │         description: p.description || "Active custom plugin",
296 │         customToolCount: p.customTools ? p.customTools.length : 0,
297 │       });
298 │     }
299 │     return list;
300 │   }
301 │ }
302 │ 
303 │ function sha256(content: string): string {
304 │   return createHash("sha256").update(content).digest("hex");
305 │ }

