453	  // GV-1 `commands.disable_allow_rules`: the operator's `allow` rules are not used; `prompt` and `forbidden` keep working.
454	  const ruleVerdict = operatorVerdict?.decision === "allow" && managed.commands.disable_allow_rules.value ? null : operatorVerdict;
455	  const recordRule = (verdict: CommandVerdict, effectText: CommandRuleDecision["effect"]): void => {
