19	const LIFECYCLE: Record<DurableOperationState["status"], DurableTaskState["status"]> = {
20	  RUNNING: "in_progress",
21	  WAITING: "in_progress",
22	  BLOCKED: "in_progress",
23	  PAUSED: "in_progress",
24	  COMPLETE: "completed",
25	  CANCELLED: "interrupted",
26	};
