28	/** Operations are durable tasks: the same atomic, workspace-bound task store that turn recovery uses. */
29	export class OperationStore {
30	  private readonly onDiagnostic?: OperationDiagnosticHandler;
31	  readonly manager: DurableStateManager;
32	  private readonly workspace: WorkspacePath;
33	  private readonly accountIdentityHome: string;
34	
35	  /** `baseDir` defaults to the task store turn recovery uses (~/.nexus/tasks). */
36	  constructor(workspace: string, baseDir?: string, accountIdentityHome = credentialStorageHome(), onDiagnostic?: OperationDiagnosticHandler) {
37	    this.onDiagnostic = onDiagnostic;
38	    this.workspace = WorkspacePath.fromSelectedWorkspace(path.resolve(workspace));
39	    this.manager = new DurableStateManager({ ...(baseDir ? { baseDir } : {}), workspacePaths: [this.workspace] });
40	    this.accountIdentityHome = accountIdentityHome;
41	  }
42	
43	  private preflightFutureVersion(id: string): void {
44	    const version = this.manager.readRawOperationSchemaVersion(id);
45	    if (typeof version === "number" && Number.isInteger(version) && version > CURRENT_OPERATION_SCHEMA_VERSION) {
46	      throw new UnsupportedOperationSchemaError(version);
47	    }
48	  }
49	
50	  has(id: string): boolean {
51	    return this.manager.hasTaskState(id);
52	  }
53	
54	  save(op: DurableOperationState): void {
55	    this.preflightFutureVersion(op.id);
56	    validateOperationState(op);
57	    op = migrateLegacyAccountIdentities(op, createOperationAccountIdentity(this.accountIdentityHome));
58	    const existing = this.manager.hasTaskState(op.id) ? this.manager.loadTaskState(op.id) : undefined;
59	    // A newer operation document is never overwritten by an older build. Writing over it would destroy the only copy
60	    // a later build can read, which is exactly what the load gate refuses to do.
61	    const onDisk = existing?.operation?.schemaVersion;
62	    if (typeof onDisk === "number" && onDisk > CURRENT_OPERATION_SCHEMA_VERSION) throw new UnsupportedOperationSchemaError(onDisk);
63	    // A v1.0.0 operation document is upgraded by this write. Keep the record this build cannot re-create, once,
64	    // before the first v2 write, so an operator can diff or restore it. The envelope's own migration backup is a
65	    // different file and a different concern.
66	    if (existing?.operation && needsMigrationBackup(onDisk)) {
67	      this.backupBeforeMigration(op.id, typeof onDisk === "number" ? onDisk : LEGACY_OPERATION_SCHEMA_VERSION);
68	    }
69	    const state: DurableTaskState = {
70	      schemaVersion: 1,
71	      taskId: op.id,
72	      sessionId: op.id,
73	      id: op.id,
74	      title: `Operation: ${op.objective.slice(0, 80)}`,
75	      workspacePath: this.workspace.value,
76	      workspace: this.workspace.value,
77	      createdAt: existing?.createdAt ?? op.createdAt,
78	      updatedAt: op.updatedAt,
79	      status: LIFECYCLE[op.status],
80	      activePlan: op.units.map((u) => ({ name: u.title, status: u.status === "COMPLETE" ? "completed" : u.status === "RUNNING" ? "in_progress" : "pending", detail: u.status })),
81	      milestones: existing?.milestones ?? [],
82	      // Goals keep their immutable objective and requirement ledger in this same durable task record.
83	      // Operation transitions must not erase it when the operation snapshot is rewritten.
84	      objective: existing?.objective ?? null,
85	      validationReceipts: [],
86	      messages: [],
87	      currentOperation: null,
88	      operation: op,
89	    };
90	    this.manager.saveTaskState(state, [this.workspace]);
91	  }
92	
93	  load(id: string): DurableOperationState {
94	    this.preflightFutureVersion(id);
95	    const state = this.manager.loadTaskState(id, this.workspace.value, [this.workspace]);
96	    if (!state.operation) throw new Error(`Task ${id} is not an operation`);
97	    let migrated: DurableOperationState;
98	    try {
99	      migrated = migrateOperationState(state.operation);
100	    } catch (error) {
101	      if (!(error instanceof InvalidOperationStateError)) throw error;
102	      // Structurally invalid is the operation-document analogue of an unparseable envelope: quarantine it and report
103	      // where it went, rather than leaving a record that will keep failing every later load.
104	      const quarantined = this.manager.quarantineFile(this.manager.getStateFilePath(id));
105	      throw new Error(`Operation ${id} is invalid: ${error.message} (quarantined to ${quarantined})`);
106	    }
107	    return migrateLegacyAccountIdentities(migrated, createOperationAccountIdentity(this.accountIdentityHome));
108	  }
109	
110	  /** Replay-only read: migrate and protect in memory under the store guard, never publish or quarantine the record. */
111	  loadForReplay(id: string): DurableOperationState {
112	    return withStateStoreGuard(this.manager.getBaseDir(), () => {
113	      const raw = JSON.parse(fs.readFileSync(this.manager.getStateFilePath(id), "utf8"));
114	      if (!raw || typeof raw !== "object" || Array.isArray(raw)) throw new Error(`Task ${id} is invalid`);
115	      const version = raw.schemaVersion ?? 0;
116	      if (typeof version === "number" && Number.isInteger(version) && version > CURRENT_STATE_SCHEMA_VERSION) {
117	        throw new UnsupportedSchemaVersionError(version);
118	      }
119	      if (!raw.operation) throw new Error(`Task ${id} is not an operation`);
120	      const opVersion = raw.operation.schemaVersion;
121	      if (typeof opVersion === "number" && Number.isInteger(opVersion) && opVersion > CURRENT_OPERATION_SCHEMA_VERSION) {
122	        throw new UnsupportedOperationSchemaError(opVersion);
123	      }
124	      const protectedRecord = redactTaskStateForPersistence(raw as DurableTaskState, [this.workspace]);
125	      return migrateOperationState(protectedRecord.operation);
126	    });
127	  }
128	
129	  /** Replay-only listing with the same no-publication guarantee as loadForReplay. */
130	  listForReplay(): DurableOperationState[] {
131	    const ids = withStateStoreGuard(this.manager.getBaseDir(), () =>
132	      fs.readdirSync(this.manager.getBaseDir())
133	        .filter((name) => name.endsWith(".json"))
134	        .map((name) => name.slice(0, -".json".length)),
135	    );
136	    const out: DurableOperationState[] = [];
137	    for (const id of ids) {
138	      try {
139	        out.push(this.loadForReplay(id));
140	      } catch (error) {
141	        if (error instanceof UnsupportedOperationSchemaError || error instanceof UnsupportedSchemaVersionError) throw error;
142	      }
143	    }
144	    return out;
145	  }
146	
147	  /** Status/export callers migrate legacy IDs on disk only when they can hold the operation lock. */
148	  loadForInspection(id: string): DurableOperationState {
149	    let release: (() => void) | undefined;
150	    try {
151	      release = this.acquire(id);
152	    } catch (error) {
