154	    }
155	    try {
156	      const operation = this.load(id);
157	      if (release) this.save(operation);
158	      return operation;
159	    } finally {
160	      release?.();
161	    }
162	  }
163	
164	  list(): DurableOperationState[] {
165	    const out: DurableOperationState[] = [];
166	    for (const t of this.manager.listTasks()) {
167	      if (!t.title.startsWith("Operation: ")) continue;
168	      try {
169	        out.push(this.load(t.taskId));
170	      } catch (error) {
171	        // A record from a newer build is a real condition the operator must see, not a record to skip silently.
172	        if (error instanceof AccountIdentityError || error instanceof UnsupportedOperationSchemaError) throw error;
173	      }
174	    }
175	    return out;
176	  }
177	
178	  /** Status/export listing persists each legacy migration only when its operation lock is available. */
179	  listForInspection(): DurableOperationState[] {
180	    const out: DurableOperationState[] = [];
181	    for (const task of this.manager.listTasks()) {
182	      if (!task.title.startsWith("Operation: ")) continue;
183	      try {
184	        out.push(this.loadForInspection(task.taskId));
185	      } catch (error) {
186	        if (error instanceof AccountIdentityError || error instanceof UnsupportedOperationSchemaError) throw error;
187	      }
188	    }
189	    return out;
190	  }
