192	  /**
193	   * One driver per operation: a second process resuming it would execute its units twice. The lock names the
194	   * holder's pid; a lock whose holder on this host is gone is stale and taken over, and so is an unreadable lock
195	   * untouched for OPERATION_LOCK_UNREADABLE_GRACE_MS (its holder died mid-write). Takeover is serialised through a
196	   * kernel-owned guard and unlinks only the file that was judged stale, so two resumers cannot both take it.
197	   * Returns the release function.
198	   * Assumptions: the unreadable-lock rule compares the lock file's mtime with this process's clock, so it holds on one
199	   * host and one filesystem (NFS, or clock skew beyond the grace, can take a live lock over early). The stale takeover
200	   * depends on the `flock` utility (/usr/bin/flock); without it a stale lock fails closed with a manual-removal message.
201	   */
202	  acquire(id: string): () => void {
203	    const lockPath = path.join(this.manager.getBaseDir(), `${id}.lock`);
204	    const create = () => fs.writeFileSync(lockPath, JSON.stringify({ pid: process.pid, host: os.hostname(), at: new Date().toISOString() }), { flag: "wx" });
205	    const locked = (holder: { pid?: number; host?: string }) =>
206	      new OperationLockedError(`Operation ${id} is already being driven by pid ${holder.pid ?? "?"} on ${holder.host ?? "?"} (lock ${lockPath}).`);
207	    try {
208	      create();
209	    } catch (err: any) {
210	      if (err?.code !== "EEXIST") throw err;
211	      const judged = this.judgeLock(lockPath);
212	      if (!judged.stale) throw locked(judged.holder);
213	      let guard: FileGuard | null;
214	      try {
215	        guard = acquireFileGuard(`${lockPath}.reclaim`, { label: "Operation lock reclaim guard" });
216	      } catch (guardError) {
217	        throw new OperationLockedError(`Operation ${id} has a stale lock at ${lockPath} that cannot be taken over safely here (${(guardError as Error).message}); remove it by hand once no nexus command is using this workspace.`);
218	      }
219	      if (!guard) throw locked(judged.holder);
220	      try {
221	        operationLockSeams.afterStaleCheck?.();
222	        const now = this.judgeLock(lockPath, false);
223	        if (!now.stale || now.ino !== judged.ino || now.mtimeNs !== judged.mtimeNs) throw locked(now.holder);
224	        fs.unlinkSync(lockPath);
225	        try {
226	          create();
227	        } catch (createError: any) {
228	          if (createError?.code === "EEXIST") throw locked({});
229	          throw createError;
230	        }
231	      } finally {
232	        releaseFileGuard(guard);
233	      }
234	    }
235	    return () => {
236	      try {
237	        if (JSON.parse(fs.readFileSync(lockPath, "utf-8")).pid === process.pid) fs.rmSync(lockPath, { force: true });
238	      } catch {
239	        reportOperationDiagnostic(this.onDiagnostic, "persistence", "lock_release_failed");
240	      }
241	    };
242	  }
243	
244	  private judgeLock(lockPath: string, report = true): { stale: boolean; holder: { pid?: number; host?: string; at?: string }; ino?: bigint; mtimeNs?: bigint } {
245	    let stat: fs.BigIntStats;
246	    try {
247	      stat = fs.lstatSync(lockPath, { bigint: true });
248	    } catch {
249	      return { stale: false, holder: {} };
250	    }
251	    let holder: { pid?: number; host?: string; at?: string } | undefined;
252	    try {
253	      const parsed = JSON.parse(fs.readFileSync(lockPath, "utf-8"));
254	      if (parsed && typeof parsed === "object") holder = parsed;
255	    } catch {
256	      if (report) reportOperationDiagnostic(this.onDiagnostic, "persistence", "lock_read_failed");
257	    }
258	    const identity = { ino: stat.ino, mtimeNs: stat.mtimeNs };
259	    if (!holder) return { stale: Date.now() - Number(stat.mtimeNs / 1_000_000n) > OPERATION_LOCK_UNREADABLE_GRACE_MS, holder: {}, ...identity };
260	    // A lock written before this host last booted is stale even if its pid has since been reused.
261	    const beforeBoot = holder.at !== undefined && Date.parse(holder.at) < Date.now() - os.uptime() * 1000;
262	    const stale = holder.host === os.hostname() && (beforeBoot || holder.pid === undefined || !processAlive(holder.pid));
263	    return { stale, holder, ...identity };
264	  }
265	
266	  /** Returns the live lock holder for an operation, or undefined when there is no readable live lock by another process. */
267	  activeLock(id: string): { pid?: number; host?: string; at?: string } | undefined {
268	    const lockPath = path.join(this.manager.getBaseDir(), `${id}.lock`);
269	    const judged = this.judgeLock(lockPath, false);
270	    if (judged.stale || judged.holder.pid === undefined) return undefined;
271	    if (judged.holder.pid === process.pid) return undefined;
272	    return judged.holder;
273	  }
274	
275	  /** Most recently updated operation in this workspace that can resume after restart. */
276	  latestResumable(): DurableOperationState | undefined {
277	    return this.list().find((op) => op.status === "WAITING" || op.status === "RUNNING" || op.status === "PAUSED");
278	  }
279	
280	  /**
281	   * Keeps the record this build is about to upgrade, once. Refuses to overwrite an existing copy whose bytes differ:
282	   * an earlier migration already produced it, and silently replacing it would destroy the only v1 evidence.
283	   */
284	  private backupBeforeMigration(id: string, fromVersion: unknown): void {
285	    const record = path.join(this.manager.getBaseDir(), `${id}.json`);
286	    const backup = `${record}.pre-migration-v${String(fromVersion)}`;
287	    let bytes: Buffer;
288	    try {
289	      bytes = fs.readFileSync(record);
290	    } catch (error: any) {
291	      // The record was just read to decide this backup was needed; its absence is a real problem, not a reason to skip.
292	      throw new Error(`Operation ${id}: cannot read ${record} to keep a pre-migration copy (${String(error?.message ?? error)})`);
293	    }
294	    if (fs.existsSync(backup)) {
295	      const existing = fs.readFileSync(backup);
296	      if (!existing.equals(bytes)) {
297	        throw new Error(
298	          `Operation ${id}: cannot migrate the operation record because ${backup} already exists with different content. ` +
299	            `Move it aside to continue, or restore it to read the record with the build that wrote it.`,
300	        );

