  1 │ /**
  2 │  * GV-1 enforcement: the managed policy of this process.
  3 │  *
  4 │  * The two managed tiers (system and user) are read once per process, on first use, and kept frozen: a later change to
  5 │  * either file, to HOME or to anything else does not reach a running process. A managed file that exists and cannot be
  6 │  * used makes every use throw the same `ManagedPolicyError`; the files are not read again. A workspace's project file
  7 │  * is read per workspace (a process works in several: worktrees, a verify base tree) and merged under the tiers that
  8 │  * were already read, so a project file can only ever add restrictions to them.
  9 │  *
 10 │  * Who acts on it: index.ts reads it at startup (a broken managed file ends the process there); config.ts refuses at
 11 │  * launch what it disables; approval_policy.ts clamps every approval decision; dispatch_tool_call.ts applies its
 12 │  * command prefixes and egress allowlist; security.ts takes the protected paths, verification mode and inspector floor
 13 │  * from it; workspace_trust.ts asks it whether the trust variable counts; agent.ts clamps a runtime mode change.
 14 │  *
 15 │  * Nothing here reads an environment variable or a command-line argument, and nothing exported from here replaces,
 16 │  * relocates or switches off the process policy: `createPolicyHost` builds a separate host from explicit inputs (tests
 17 │  * use it), and the process host below is a module-private constant built from `resolveProductionPolicyInputs`.
 18 │  */
 19 │ import * as path from "node:path";
 20 │ import { resolveProductionPolicyInputs, type ProductionPolicyInputs } from "./managed_policy_inputs.js";
 21 │ import {
 22 │   loadManagedTiers,
 23 │   loadProjectPolicy,
 24 │   ManagedPolicyError,
 25 │   MANAGED_POLICY_EXIT_CODE,
 26 │   recordProjectPolicyApproval,
 27 │   type LoadedPolicy,
 28 │   type ManagedTiers,
 29 │ } from "./managed_policy_load.js";
 30 │ import { describeSource, mergePolicies, requiresHuman, type EffectivePolicy, type HumanEffect, type PolicySource } from "./managed_policy.js";
 31 │ 
 32 │ /** The managed tiers as read, and their merge (no project tier). Frozen. */
 33 │ export interface ManagedPolicyState {
 34 │   tiers: ManagedTiers;
 35 │   effective: EffectivePolicy;
 36 │ }
 37 │ 
 38 │ /** What the caller knows about trust in a workspace; this module reads neither the trust store nor the environment. */
 39 │ export interface WorkspaceTrustFacts {
 40 │   /** The operator's trust store lists the workspace. */
 41 │   workspaceTrusted: boolean;
 42 │   /** `NEXUS_TRUST_WORKSPACE=1` was set. */
 43 │   envTrustRequested: boolean;
 44 │ }
 45 │ 
 46 │ export interface PolicyHost {
 47 │   /** The managed tiers, read on the first call and never again. Throws the first call's `ManagedPolicyError` every time. */
 48 │   managed(): ManagedPolicyState;
 49 │   /** The policy in force in `workspace` (its real path): its project file merged under the managed tiers. */
 50 │   forWorkspace(workspace: string, trust: WorkspaceTrustFacts): LoadedPolicy;
 51 │   /**
 52 │    * Records the operator's approval of the workspace's current project file (by the hash of its bytes), so that its
 53 │    * relaxations apply until the file changes. Returns the hash, or undefined when there is no readable file to approve.
 54 │    */
 55 │   approveProjectPolicy(workspace: string, approvedAt: string): string | undefined;
 56 │ }
 57 │ 
 58 │ function deepFreeze<T>(value: T): T {
 59 │   if (value && typeof value === "object" && !Object.isFrozen(value)) {
 60 │     Object.freeze(value);
 61 │     for (const member of Object.values(value)) deepFreeze(member);
 62 │   }
 63 │   return value;
 64 │ }
 65 │ 
 66 │ /** A host over explicit inputs. `resolve` is called once for the managed tiers; only the approval store's path is taken from a later call. */
 67 │ export function createPolicyHost(resolve: () => ProductionPolicyInputs): PolicyHost {
 68 │   let loaded: { inputs: ProductionPolicyInputs; state?: ManagedPolicyState; error?: ManagedPolicyError } | undefined;
 69 │   const managed = (): ManagedPolicyState => {
 70 │     if (!loaded) {
 71 │       const inputs = resolve();
 72 │       try {
 73 │         const tiers = loadManagedTiers(inputs);
 74 │         loaded = { inputs, state: deepFreeze({ tiers, effective: mergePolicies(tiers.system, tiers.user) }) };
 75 │       } catch (error) {
 76 │         if (!(error instanceof ManagedPolicyError)) throw error;
 77 │         loaded = { inputs, error };
 78 │       }
 79 │     }
 80 │     if (loaded.error) throw loaded.error;
 81 │     return loaded.state!;
 82 │   };
 83 │   const forWorkspace = (workspace: string, trust: WorkspaceTrustFacts): LoadedPolicy => {
 84 │     const { tiers } = managed();
 85 │     return loadProjectPolicy(tiers, { workspace, trust: { ...trust, storePath: resolve().trustStorePath }, fs: loaded!.inputs.fs });
 86 │   };
 87 │   return {
 88 │     managed,
 89 │     forWorkspace,
 90 │     approveProjectPolicy(workspace, approvedAt) {
 91 │       const sha256 = forWorkspace(workspace, { workspaceTrusted: true, envTrustRequested: false }).project.sha256;
 92 │       if (sha256 === undefined) return undefined;
 93 │       recordProjectPolicyApproval({ fs: loaded!.inputs.fs, storePath: resolve().trustStorePath, workspace, sha256, approvedAt });
 94 │       return sha256;
 95 │     },
 96 │   };
 97 │ }
 98 │ 
 99 │ const processHost = createPolicyHost(resolveProductionPolicyInputs);
100 │ 
101 │ /** The policy host of this process. */
102 │ export function processPolicyHost(): PolicyHost {
103 │   return processHost;
104 │ }
105 │ 
106 │ /** The effective managed policy of this process (system and user tiers). Throws `ManagedPolicyError`. */
107 │ export function managedPolicy(): EffectivePolicy {
108 │   return processHost.managed().effective;
109 │ }
110 │ 
111 │ /**
112 │  * Startup: reads the managed tiers now. A managed policy that exists and cannot be used ends the process: the two
113 │  * lines of the error on stderr, exit code 2. Commands that must run with a broken policy do not call this.
114 │  */
115 │ export function requireManagedPolicyAtStartup(): void {
116 │   try {
117 │     processHost.managed();
118 │   } catch (error) {
119 │     if (!(error instanceof ManagedPolicyError)) throw error;
120 │     process.stderr.write(`${error.message}\n`);
121 │     process.exit(MANAGED_POLICY_EXIT_CODE);
122 │   }
123 │ }
124 │ 
125 │ const told = new Set<string>();
126 │ 
127 │ /** Tells the operator something a policy decided, once per process, on stderr. */
128 │ export function emitPolicyNotice(notice: string): void {
129 │   if (told.has(notice)) return;
130 │   told.add(notice);
131 │   process.stderr.write(`${notice}\n`);
132 │ }
133 │ 
134 │ /** How a project file whose relaxations were not applied gets approved in this release. */
135 │ export function approvalHint(policy: LoadedPolicy): string | undefined {
136 │   if (policy.effective.verification.relaxationStatus !== "not_approved") return undefined;
137 │   return `nexus: to apply the relaxations of ${policy.project.file}, review the file and approve it with \`nexus trust ${path.dirname(policy.project.file)}\`; a later change to the file needs a new approval.`;
138 │ }
139 │ 
140 │ /** The approval settings a tool call is decided under. Structurally the `PolicyContext` members this module clamps. */
141 │ interface ApprovalSettings {
142 │   mode: "auto" | "review" | "read-only";
143 │   fullAccess?: boolean;
144 │   policyRequiresHuman?: boolean;
145 │ }
146 │ 
147 │ /** Why a call needs a human decision whatever the approval mode: the text to show and the tier it comes from. */
148 │ export interface HumanRequirement {
149 │   message: string;
150 │   source: PolicySource;
151 │ }
152 │ 
153 │ const HUMAN_EFFECTS: readonly string[] = ["exec", "write_workspace", "egress"] satisfies HumanEffect[];
154 │ 
155 │ /** `approval.require_human` against a call's effect class. */
156 │ export function humanRequirementForEffect(policy: EffectivePolicy, effect: string): HumanRequirement | undefined {
157 │   if (!HUMAN_EFFECTS.includes(effect)) return undefined;
158 │   const answer = requiresHuman(policy, effect as HumanEffect);
159 │   return answer.required ? { message: answer.message!, source: answer.source } : undefined;
160 │ }
161 │ 
162 │ /**
163 │  * The approval settings as the policy lets them stand, whatever built them: mode `auto` becomes `review` under
164 │  * `approval.disable_auto`, full access is dropped under `approval.disable_full_access`, and `human` (a managed
165 │  * `prompt` rule or `approval.require_human`) makes the call ask in every mode. Restrict-only: nothing is ever raised.
166 │  */
167 │ export function clampApprovalSettings<T extends ApprovalSettings>(policy: EffectivePolicy, settings: T, human?: HumanRequirement): T {
168 │   const mode = settings.mode === "auto" && policy.approval.disable_auto.value ? "review" : settings.mode;
169 │   const fullAccess = Boolean(settings.fullAccess) && !policy.approval.disable_full_access.value && mode === settings.mode;
170 │   return { ...settings, mode, fullAccess, ...(human ? { policyRequiresHuman: true } : {}) };
171 │ }
172 │ 
173 │ /** The tier to name beside a decision the approval mode made: the tier that disabled what was asked for, else the default. */
174 │ export function approvalDecisionSource(policy: EffectivePolicy, asked: ApprovalSettings): PolicySource {
175 │   if (asked.mode === "auto" && policy.approval.disable_auto.value) return policy.approval.disable_auto.source;
176 │   if (asked.fullAccess && policy.approval.disable_full_access.value) return policy.approval.disable_full_access.source;
177 │   return { tier: "default", key: "approval.mode" };
178 │ }
