      if (problem) throw new OperationSpecError(`work unit '${unit.id}' ${problem}`);
    }
    if (unit.inputs !== undefined) {
      const problem = specialistInputsProblem(unit.inputs);
      if (problem) throw new OperationSpecError(`work unit '${unit.id}' ${problem}`);
    }
    if (unit.requires !== undefined) {
