  1 │ /**
  2 │  * Approval Policy Framework
  3 │  * Nexus SPEC-01 §5.1, §5.2 — Safe Execution Defaults (DEC-01, as amended)
  4 │  */
  5 │ import { EffectClass } from "./capabilities.js";
  6 │ import type { EffectivePolicy } from "./managed_policy.js";
  7 │ import { clampApprovalSettings, humanRequirementForEffect, managedPolicy } from "./policy_runtime.js";
  8 │ 
  9 │ export type ApprovalMode = "auto" | "review" | "read-only";
 10 │ 
 11 │ export interface PolicyContext {
 12 │   mode: ApprovalMode;
 13 │   /** Workspace trust is reported separately; it never selects or widens tool authority. */
 14 │   trusted: boolean;
 15 │   sandbox?: boolean | string;
 16 │   approvedEgressOrigins?: Set<string>;
 17 │   egressOrigin?: string;
 18 │   isUntrustedSource?: boolean;
 19 │   fullAccess?: boolean;
 20 │   /**
 21 │    * GV-1: managed policy requires a human decision for this call (a managed `prompt` command rule, or its effect is in
 22 │    * `approval.require_human`). It holds in every mode, full access included; the caller names the policy source.
 23 │    */
 24 │   policyRequiresHuman?: boolean;
 25 │ }
 26 │ 
 27 │ export class ApprovalPolicy {
 28 │   /** `policy` gives the effective managed policy every decision is clamped under; the process's own when omitted. */
 29 │   constructor(private readonly policy: () => EffectivePolicy = managedPolicy) {}
 30 │ 
 31 │   /**
 32 │    * Decides whether an operator decision is required before executing a capability with effect class `effect`.
 33 │    * Permission mode controls tool approvals independently of workspace trust:
 34 │    * - Review mode asks before writes, commands and egress.
 35 │    * - Auto mode allows writes and commands; egress asks once per origin per session.
 36 │    * - Untrusted context sources remain distinguishable from workspace trust.
 37 │    * - --yes / fullAccess forces auto for write and exec.
 38 │    * - `policyRequiresHuman` (managed policy) asks in every mode, before any of the above.
 39 │    */
 40 │   public requiresDecision(effect: EffectClass, context: PolicyContext): boolean {
 41 │     // GV-1: managed policy is applied here, in the one gate every caller asks, so no caller's context outranks it.
 42 │     // A required human outranks every mode: full access and an already-approved egress origin do not answer for it.
 43 │     const managed = this.policy();
 44 │     if (context.policyRequiresHuman || humanRequirementForEffect(managed, effect)) return true;
 45 │     const { mode, approvedEgressOrigins, egressOrigin, isUntrustedSource, fullAccess } = clampApprovalSettings(managed, context);
 46 │ 
 47 │     // Full access (--yes / operator force auto) bypasses confirmation prompts for write and exec
 48 │     if (fullAccess) {
 49 │       if (effect === "egress") {
 50 │         if (egressOrigin && approvedEgressOrigins?.has(egressOrigin)) return false;
 51 │         // In fullAccess / --yes mode, egress does not prompt if no interactive operator is present
 52 │         return false;
 53 │       }
 54 │       return false;
 55 │     }
 56 │ 
 57 │     // read_workspace, delegate, internal never require an operator decision
 58 │     if (effect === "read_workspace" || effect === "delegate" || effect === "internal") {
 59 │       return false;
 60 │     }
 61 │ 
 62 │     if (mode === "read-only") {
 63 │       // In read-only mode, mutating tools are denied directly by read-only policy rather than prompting the operator
 64 │       return false;
 65 │     }
 66 │ 
 67 │     if (mode === "review") {
 68 │       if (effect === "write_workspace" || effect === "exec") {
 69 │         return true;
 70 │       }
 71 │       if (effect === "egress") {
 72 │         if (egressOrigin && approvedEgressOrigins?.has(egressOrigin)) {
 73 │           return false;
 74 │         }
 75 │         return true;
 76 │       }
 77 │       if (effect === "context_inject") return Boolean(isUntrustedSource);
 78 │       return false;
 79 │     }
 80 │ 
 81 │     // mode === "auto"
 82 │     if (mode === "auto") {
 83 │       if (effect === "write_workspace") {
 84 │         return false;
 85 │       }
 86 │       if (effect === "exec") {
 87 │         return false;
 88 │       }
 89 │       if (effect === "egress") {
 90 │         // Egress asks on the first call per origin per session, then allowed for that origin
 91 │         if (egressOrigin && approvedEgressOrigins?.has(egressOrigin)) {
 92 │           return false;
 93 │         }
 94 │         return true;
 95 │       }
 96 │       if (effect === "context_inject") {
 97 │         return Boolean(isUntrustedSource);
 98 │       }
 99 │       return false;
100 │     }
101 │ 
102 │     return false;
103 │   }
104 │ }
105 │ 
106 │ export const defaultApprovalPolicy = new ApprovalPolicy();

