 1 │ /**
 2 │  * VR-2: the process a server forks to run one verification. `verifyChange` runs every repository process synchronously,
 3 │  * so it cannot run on a server's event loop. One job arrives over IPC and one reply goes back: the result, a usage
 4 │  * error, or "interrupted". Nothing is written to stdout.
 5 │  *
 6 │  * The job carries only the operator's verifier, deliverables and deadline. Approval of a discovered verifier, approval
 7 │  * of a verification edit and a sandbox setting have no field here, so no caller of a server can reach them.
 8 │  */
 9 │ import { verifyChange, VerifyInterrupted, VerifyUsageError } from "./verify.js";
10 │ import { VERIFY_WORKER_TAG, type VerifyWorkerJob, type VerifyWorkerReply } from "./verify_service.js";
11 │ 
12 │ const abort = new AbortController();
13 │ // SIGTERM is the server's cancellation. A lost channel means the server is gone and nobody can read a verdict.
14 │ process.on("SIGTERM", () => abort.abort());
15 │ process.on("disconnect", () => abort.abort());
16 │ 
17 │ function send(reply: VerifyWorkerReply): Promise<void> {
18 │   return new Promise((resolve) => {
19 │     if (!process.connected) return resolve();
20 │     process.send!({ tag: VERIFY_WORKER_TAG, ...reply }, () => resolve());
21 │   });
22 │ }
23 │ 
24 │ function isJob(value: any): value is VerifyWorkerJob {
25 │   return value?.tag === VERIFY_WORKER_TAG
26 │     && typeof value.request?.worktree === "string" && typeof value.request?.base === "string"
27 │     && (value.operator?.verifierCommand === undefined || typeof value.operator.verifierCommand === "string")
28 │     && Array.isArray(value.operator?.deliverables) && value.operator.deliverables.every((file: unknown) => typeof file === "string")
29 │     && Number.isInteger(value.operator?.timeoutSecs);
30 │ }
31 │ 
32 │ async function runJob(job: VerifyWorkerJob): Promise<VerifyWorkerReply> {
33 │   if (abort.signal.aborted) return { interrupted: true };
34 │   try {
35 │     // No `head`: the change is always the working tree on disk. No `sandbox`: the core default (confined, network off).
36 │     const result = await verifyChange(
37 │       { worktree: job.request.worktree, base: job.request.base },
38 │       { verifierCommand: job.operator.verifierCommand, deliverables: job.operator.deliverables, timeoutSecs: job.operator.timeoutSecs, signal: abort.signal },
39 │     );
40 │     return { result };
41 │   } catch (error) {
42 │     if (error instanceof VerifyInterrupted) return { interrupted: true };
