50 │   // The TypeScript loader used in tests also talks on this channel, so anything that is not the job is ignored.
51 │   if (started || (message as any)?.tag !== VERIFY_WORKER_TAG) return;
52 │   started = true;
53 │   void (isJob(message) ? runJob(message) : Promise.resolve<VerifyWorkerReply>({ failed: "malformed verification job" }))
54 │     .then(send)
55 │     .then(() => process.exit(0));
56 │ });
